#!/usr/bin/env python3
"""Writes config/quickshell/bevel/PixIcon.qml from tools/pixicons.py."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import pixicons
pixicons.check()
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "config", "quickshell", "bevel", "PixIcon.qml")
pal = ", ".join('"%s": "%s"' % kv for kv in pixicons.PAL.items())
qml = '''import QtQuick

// 16x16 pixel icons in the 9x style, drawn crisp at any whole-number scale.
// Generated by tools/mkpixicon.py from tools/pixicons.py — edit the art there.
Canvas {
    id: ic
    property string kind: "gear"
    property int zoom: 1
    property color tint: "transparent"      // replaces the accent colours (e.g. white on a coloured tile)
    implicitWidth: 16 * zoom
    implicitHeight: 16 * zoom
    renderStrategy: Canvas.Immediate
    antialiasing: false
    readonly property var pal: ({ %s })
    readonly property var bits: %s
    onKindChanged: requestPaint()
    onZoomChanged: requestPaint()
    onTintChanged: requestPaint()
    onWidthChanged: requestPaint()
    Connections { target: Theme; function onAccentChanged() { ic.requestPaint(); } }
    onPaint: {
        const ctx = getContext("2d");
        ctx.reset();
        const d = ic.bits[ic.kind] || ic.bits["gear"];
        const m = Math.min(width, height);
        const s = m >= 16 ? Math.floor(m / 16) : Math.max(0.25, m / 16);   // smaller than 16px: shrink instead of clipping
        const ox = Math.floor((width - 16 * s) / 2), oy = Math.floor((height - 16 * s) / 2);
        for (let y = 0; y < 16; y++) {
            let x = 0;
            while (x < 16) {
                const ch = d[y * 16 + x];
                let run = 1;
                while (x + run < 16 && d[y * 16 + x + run] === ch) run++;
                if (ch !== ".") {
                    ctx.fillStyle = ch === "a" ? (ic.tint.a > 0 ? ic.tint : Theme.accent) : (ch === "A" ? (ic.tint.a > 0 ? Qt.darker(ic.tint, 1.25) : Theme.accent2) : ic.pal[ch]);
                    ctx.fillRect(ox + x * s, oy + y * s, run * s, s);
                }
                x += run;
            }
        }
    }
}
''' % (pal, pixicons.qml_data())
open(out, "w").write(qml)
print("wrote", os.path.normpath(out), len(pixicons.ICONS), "icons")
